FROM jsonb_to_recordset($vt$[{"variety_id": "07ed20a3-e31e-44fe-a506-72e64221c616", "language_code": "en", "display_name": "Field Pea IPF 16-13 (Harit)", "short_description": "A tall, leafy field pea variety of 115-120 days, resistant to powdery mildew and moderately tolerant to rust.", "detailed_description": "IPF 16-13 (Harit) is a field pea variety released in 2020 by ICAR-Indian Institute of Pulses Research, Kanpur. The crop duration is 115-120 days. The plants are tall and leafy. The seeds are green in colour and round in shape. The yield is 1752 kg/ha. It is recommended for the North Eastern Plain Zone, which covers Bihar, Assam, Chhattisgarh, West Bengal and the eastern part of Uttar Pradesh. It is resistant to powdery mildew and moderately tolerant to rust.", "local_synonyms": ["IPF-16-13"]}, {"variety_id": "07ed20a3-e31e-44fe-a506-72e64221c616", "language_code": "hi", "display_name": "मटर (दलहनी) IPF 16-13 (हरित)", "short_description": "115-120 दिनों की ऊँची और पत्तेदार दलहनी मटर की किस्म, जो भभूतिया रोग (चूर्णिल आसिता) के प्रति प्रतिरोधी और रतुआ के प्रति मध्यम सहनशील है।", "detailed_description": "IPF 16-13 (हरित) दलहनी मटर की किस्म है, जिसे वर्ष 2020 में ICAR-भारतीय दलहन अनुसंधान संस्थान, कानपुर ने जारी किया। फसल की अवधि 115-120 दिन है। पौधे ऊँचे और पत्तेदार होते हैं। दाने हरे रंग के और गोल आकार के होते हैं। उपज 1752 kg/ha है। इसकी सिफारिश उत्तर-पूर्वी मैदानी क्षेत्र के लिए की गई है, जिसमें बिहार, असम, छत्तीसगढ़, पश्चिम बंगाल और उत्तर प्रदेश का पूर्वी भाग आते हैं। यह भभूतिया रोग (चूर्णिल आसिता) के प्रति प्रतिरोधी और रतुआ के प्रति मध्यम सहनशील है।", "local_synonyms": ["मटर (दलहनी)", "IPF-16-13"]}, {"variety_id": "07ed20a3-e31e-44fe-a506-72e64221c616", "language_code": "mr", "display_name": "वाटाणा (कडधान्य) IPF 16-13 (हरित)", "short_description": "115-120 दिवसांचा, उंच व भरपूर पानांचा कडधान्य वाटाण्याचा वाण; भुरी रोगास प्रतिकारक्षम आणि तांबेरा रोगास मध्यम सहनशील.", "detailed_description": "IPF 16-13 (हरित) हा कडधान्य वाटाण्याचा वाण ICAR-भारतीय कडधान्य संशोधन संस्था, कानपूर यांनी 2020 मध्ये प्रसारित केला. पिकाचा कालावधी 115-120 दिवस आहे. झाडे उंच व भरपूर पानांची असतात. दाणे हिरव्या रंगाचे व गोल आकाराचे असतात. उत्पादन 1752 kg/ha मिळते. हा वाण उत्तर-पूर्व मैदानी विभागासाठी शिफारस केलेला आहे; यात बिहार, आसाम, छत्तीसगड, पश्चिम बंगाल आणि उत्तर प्रदेशचा पूर्व भाग येतो. हा वाण भुरी रोगास प्रतिकारक्षम आणि तांबेरा रोगास मध्यम सहनशील आहे.", "local_synonyms": ["वाटाणा (कडधान्य)", "IPF-16-13"]}, {"variety_id": "07ed20a3-e31e-44fe-a506-72e64221c616", "language_code": "pa", "display_name": "ਮਟਰ IPF 16-13 (ਹਰਿਤ)", "short_description": "115-120 ਦਿਨਾਂ ਦੀ ਮਿਆਦ ਵਾਲੀ, ਉੱਚੇ ਅਤੇ ਪੱਤੇਦਾਰ ਬੂਟਿਆਂ ਵਾਲੀ ਦਾਲ ਵਾਲੇ ਮਟਰ ਦੀ ਕਿਸਮ, ਜੋ ਚਿੱਟੇ ਰੋਗ ਦੀ ਰੋਧਕ ਅਤੇ ਕੁੰਗੀ ਪ੍ਰਤੀ ਦਰਮਿਆਨੀ ਸਹਿਣਸ਼ੀਲ ਹੈ।", "detailed_description": "IPF 16-13 (ਹਰਿਤ) ਦਾਲ ਵਾਲੇ ਮਟਰ ਦੀ ਕਿਸਮ ਹੈ, ਜੋ ICAR-ਭਾਰਤੀ ਦਾਲਾਂ ਖੋਜ ਸੰਸਥਾਨ, ਕਾਨਪੁਰ ਵੱਲੋਂ 2020 ਵਿੱਚ ਜਾਰੀ ਕੀਤੀ ਗਈ। ਫ਼ਸਲ ਦੀ ਮਿਆਦ 115-120 ਦਿਨ ਹੈ। ਬੂਟੇ ਉੱਚੇ ਅਤੇ ਪੱਤੇਦਾਰ ਹੁੰਦੇ ਹਨ। ਦਾਣੇ ਹਰੇ ਰੰਗ ਦੇ ਅਤੇ ਗੋਲ ਹੁੰਦੇ ਹਨ। ਝਾੜ 1752 kg/ha ਹੈ। ਇਹ ਉੱਤਰ-ਪੂਰਬੀ ਮੈਦਾਨੀ ਖੇਤਰ ਲਈ ਸਿਫ਼ਾਰਸ਼ ਕੀਤੀ ਗਈ ਹੈ, ਜਿਸ ਵਿੱਚ ਬਿਹਾਰ, ਅਸਾਮ, ਛੱਤੀਸਗੜ੍ਹ, ਪੱਛਮੀ ਬੰਗਾਲ ਅਤੇ ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਦਾ ਪੂਰਬੀ ਹਿੱਸਾ ਸ਼ਾਮਲ ਹਨ। ਇਹ ਚਿੱਟੇ ਰੋਗ ਦੀ ਰੋਧਕ ਅਤੇ ਕੁੰਗੀ ਪ੍ਰਤੀ ਦਰਮਿਆਨੀ ਸਹਿਣਸ਼ੀਲ ਹੈ।", "local_synonyms": ["ਮਟਰ", "IPF-16-13"]}, {"variety_id": "07ed20a3-e31e-44fe-a506-72e64221c616", "language_code": "gu", "display_name": "વટાણા IPF 16-13 (હરિત)", "short_description": "115-120 દિવસની, ઊંચા અને પાંદડાવાળા છોડવાળી કઠોળ વટાણાની જાત, જે ભૂકી છારા સામે પ્રતિકારક અને ગેરુ સામે મધ્યમ સહનશીલ છે.", "detailed_description": "IPF 16-13 (હરિત) કઠોળ વટાણાની જાત છે, જે ICAR-ભારતીય કઠોળ સંશોધન સંસ્થા, કાનપુર દ્વારા 2020માં બહાર પાડવામાં આવી. પાકનો સમયગાળો 115-120 દિવસ છે. છોડ ઊંચા અને પાંદડાવાળા હોય છે. દાણા લીલા રંગના અને ગોળ આકારના હોય છે. ઉત્પાદન 1752 kg/ha છે. તેની ભલામણ ઉત્તર-પૂર્વીય મેદાની વિસ્તાર માટે કરવામાં આવી છે, જેમાં બિહાર, આસામ, છત્તીસગઢ, પશ્ચિમ બંગાળ અને ઉત્તર પ્રદેશનો પૂર્વ ભાગ આવે છે. તે ભૂકી છારા સામે પ્રતિકારક અને ગેરુ સામે મધ્યમ સહનશીલ છે.", "local_synonyms": ["વટાણા", "IPF-16-13"]}, {"variety_id": "07ed20a3-e31e-44fe-a506-72e64221c616", "language_code": "ta", "display_name": "வயல் பட்டாணி IPF 16-13 (ஹரித்)", "short_description": "115-120 நாட்கள் வயதுடைய, உயரமான, அதிக இலைகள் கொண்ட வயல் பட்டாணி ரகம்; சாம்பல் நோய்க்கு எதிர்ப்புத் திறனும், துரு நோயை மிதமாகத் தாங்கும் திறனும் கொண்டது.", "detailed_description": "IPF 16-13 (ஹரித்) என்பது ICAR-இந்திய பயறு வகை ஆராய்ச்சி நிறுவனம், கான்பூர் 2020-ல் வெளியிட்ட வயல் பட்டாணி ரகம் ஆகும். பயிரின் வயது 115-120 நாட்கள். செடிகள் உயரமாகவும் அதிக இலைகளுடனும் இருக்கும். விதைகள் பச்சை நிறத்திலும் உருண்டை வடிவிலும் இருக்கும். மகசூல் 1752 kg/ha. இது வடகிழக்கு சமவெளி மண்டலத்திற்குப் பரிந்துரைக்கப்படுகிறது; இதில் பீகார், அசாம், சத்தீஸ்கர், மேற்கு வங்காளம் மற்றும் உத்தரப் பிரதேசத்தின் கிழக்குப் பகுதி அடங்கும். இது சாம்பல் நோய்க்கு எதிர்ப்புத் திறன் கொண்டது; துரு நோயை மிதமாகத் தாங்கும்.", "local_synonyms": ["வயல் பட்டாணி", "IPF-16-13"]}, {"variety_id": "07ed20a3-e31e-44fe-a506-72e64221c616", "language_code": "te", "display_name": "బఠాణీ IPF 16-13 (హరిత్)", "short_description": "115-120 రోజుల కాలపరిమితి గల, పొడవైన, ఆకులు ఎక్కువగా ఉండే పప్పుధాన్యపు బఠాణీ రకం; బూడిద తెగులుకు నిరోధక శక్తి, తుప్పు తెగులును మధ్యస్థంగా తట్టుకునే శక్తి కలిగి ఉంది.", "detailed_description": "IPF 16-13 (హరిత్) పప్పుధాన్యపు బఠాణీ రకం. దీనిని ICAR-భారతీయ పప్పుధాన్యాల పరిశోధన సంస్థ, కాన్పూర్ 2020లో విడుదల చేసింది. పంట కాలం 115-120 రోజులు. మొక్కలు పొడవుగా, ఆకులు ఎక్కువగా ఉంటాయి. గింజలు ఆకుపచ్చ రంగులో, గుండ్రంగా ఉంటాయి. దిగుబడి 1752 kg/ha. ఇది ఈశాన్య మైదాన మండలానికి సిఫార్సు చేయబడింది; ఇందులో బీహార్, అస్సాం, ఛత్తీస్‌గఢ్, పశ్చిమ బెంగాల్ మరియు ఉత్తర ప్రదేశ్ తూర్పు భాగం ఉన్నాయి. ఇది బూడిద తెగులుకు నిరోధక శక్తి కలిగి ఉంది మరియు తుప్పు తెగులును మధ్యస్థంగా తట్టుకుంటుంది.", "local_synonyms": ["బఠాణీ", "IPF-16-13"]}, {"variety_id": "07ed20a3-e31e-44fe-a506-72e64221c616", "language_code": "kn", "display_name": "ಬಟಾಣಿ IPF 16-13 (ಹರಿತ್)", "short_description": "115-120 ದಿನಗಳ ಅವಧಿಯ, ಎತ್ತರದ ಮತ್ತು ಹೆಚ್ಚು ಎಲೆಗಳಿರುವ ಕಾಳು ಬಟಾಣಿ ತಳಿ; ಬೂದಿ ರೋಗಕ್ಕೆ ನಿರೋಧಕ ಮತ್ತು ತುಕ್ಕು ರೋಗಕ್ಕೆ ಮಧ್ಯಮ ಸಹಿಷ್ಣು.", "detailed_description": "IPF 16-13 (ಹರಿತ್) ಕಾಳು ಬಟಾಣಿಯ ತಳಿಯಾಗಿದ್ದು, ICAR-ಭಾರತೀಯ ದ್ವಿದಳ ಧಾನ್ಯ ಸಂಶೋಧನಾ ಸಂಸ್ಥೆ, ಕಾನ್ಪುರ 2020ರಲ್ಲಿ ಬಿಡುಗಡೆ ಮಾಡಿದೆ. ಬೆಳೆಯ ಅವಧಿ 115-120 ದಿನಗಳು. ಗಿಡಗಳು ಎತ್ತರವಾಗಿದ್ದು ಹೆಚ್ಚು ಎಲೆಗಳನ್ನು ಹೊಂದಿರುತ್ತವೆ. ಕಾಳುಗಳು ಹಸಿರು ಬಣ್ಣದ ಮತ್ತು ದುಂಡಗಿನ ಆಕಾರದವು. ಇಳುವರಿ 1752 kg/ha. ಇದನ್ನು ಈಶಾನ್ಯ ಬಯಲು ವಲಯಕ್ಕೆ ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ; ಇದರಲ್ಲಿ ಬಿಹಾರ, ಅಸ್ಸಾಂ, ಛತ್ತೀಸ್‌ಗಢ, ಪಶ್ಚಿಮ ಬಂಗಾಳ ಮತ್ತು ಉತ್ತರ ಪ್ರದೇಶದ ಪೂರ್ವ ಭಾಗ ಸೇರಿವೆ. ಇದು ಬೂದಿ ರೋಗಕ್ಕೆ ನಿರೋಧಕ ಮತ್ತು ತುಕ್ಕು ರೋಗಕ್ಕೆ ಮಧ್ಯಮ ಸಹಿಷ್ಣು.", "local_synonyms": ["ಬಟಾಣಿ", "IPF-16-13"]}, {"variety_id": "091e4050-62c5-46c9-87e9-67187cfe4134", "language_code": "en", "display_name": "Field Pea IPFD 12-8 (Aakash)", "short_description": "A dwarf, leafy field pea variety of 120-130 days, yielding 25 q/ha and resistant to powdery mildew and rust.", "detailed_description": "IPFD 12-8 (Aakash) is a field pea variety released in 2020 by ICAR-Indian Institute of Pulses Research, Kanpur. The crop duration is 120-130 days. The plants are dwarf and leafy. The seeds are medium in size, round, smooth and creamish white, and the cotyledons are yellow. The yield is 25 q/ha. It is recommended for the whole of Uttar Pradesh. It is resistant to both powdery mildew and rust.", "local_synonyms": ["IPFD-12-8"]}, {"variety_id": "091e4050-62c5-46c9-87e9-67187cfe4134", "language_code": "hi", "display_name": "मटर (दलहनी) IPFD 12-8 (आकाश)", "short_description": "120-130 दिनों की बौनी और पत्तेदार दलहनी मटर की किस्म, जिसकी उपज 25 q/ha है और जो भभूतिया रोग (चूर्णिल आसिता) व रतुआ के प्रति प्रतिरोधी है।", "detailed_description": "IPFD 12-8 (आकाश) दलहनी मटर की किस्म है, जिसे वर्ष 2020 में ICAR-भारतीय दलहन अनुसंधान संस्थान, कानपुर ने जारी किया। फसल की अवधि 120-130 दिन है। पौधे बौने और पत्तेदार होते हैं। दाने मध्यम आकार के, गोल, चिकने और मलाईदार सफ़ेद रंग के होते हैं, तथा बीजपत्र पीले होते हैं। उपज 25 q/ha है। इसकी सिफारिश पूरे उत्तर प्रदेश के लिए की गई है। यह भभूतिया रोग (चूर्णिल आसिता) और रतुआ, दोनों के प्रति प्रतिरोधी है।", "local_synonyms": ["मटर (दलहनी)", "IPFD-12-8"]}, {"variety_id": "091e4050-62c5-46c9-87e9-67187cfe4134", "language_code": "mr", "display_name": "वाटाणा (कडधान्य) IPFD 12-8 (आकाश)", "short_description": "120-130 दिवसांचा, बुटका व भरपूर पानांचा कडधान्य वाटाण्याचा वाण; उत्पादन 25 q/ha, भुरी व तांबेरा रोगांस प्रतिकारक्षम.", "detailed_description": "IPFD 12-8 (आकाश) हा कडधान्य वाटाण्याचा वाण ICAR-भारतीय कडधान्य संशोधन संस्था, कानपूर यांनी 2020 मध्ये प्रसारित केला. पिकाचा कालावधी 120-130 दिवस आहे. झाडे बुटकी व भरपूर पानांची असतात. दाणे मध्यम आकाराचे, गोल, गुळगुळीत व मलईसारख्या पांढऱ्या रंगाचे असतात आणि बीजदल पिवळे असतात. उत्पादन 25 q/ha मिळते. हा वाण संपूर्ण उत्तर प्रदेशासाठी शिफारस केलेला आहे. हा वाण भुरी व तांबेरा या दोन्ही रोगांस प्रतिकारक्षम आहे.", "local_synonyms": ["वाटाणा (कडधान्य)", "IPFD-12-8"]}, {"variety_id": "091e4050-62c5-46c9-87e9-67187cfe4134", "language_code": "pa", "display_name": "ਮਟਰ IPFD 12-8 (ਆਕਾਸ਼)", "short_description": "120-130 ਦਿਨਾਂ ਦੀ ਮਿਆਦ ਵਾਲੀ, ਮਧਰੇ ਅਤੇ ਪੱਤੇਦਾਰ ਬੂਟਿਆਂ ਵਾਲੀ ਦਾਲ ਵਾਲੇ ਮਟਰ ਦੀ ਕਿਸਮ, ਜਿਸ ਦਾ ਝਾੜ 25 q/ha ਹੈ ਅਤੇ ਜੋ ਚਿੱਟੇ ਰੋਗ ਅਤੇ ਕੁੰਗੀ ਦੀ ਰੋਧਕ ਹੈ।", "detailed_description": "IPFD 12-8 (ਆਕਾਸ਼) ਦਾਲ ਵਾਲੇ ਮਟਰ ਦੀ ਕਿਸਮ ਹੈ, ਜੋ ICAR-ਭਾਰਤੀ ਦਾਲਾਂ ਖੋਜ ਸੰਸਥਾਨ, ਕਾਨਪੁਰ ਵੱਲੋਂ 2020 ਵਿੱਚ ਜਾਰੀ ਕੀਤੀ ਗਈ। ਫ਼ਸਲ ਦੀ ਮਿਆਦ 120-130 ਦਿਨ ਹੈ। ਬੂਟੇ ਮਧਰੇ ਅਤੇ ਪੱਤੇਦਾਰ ਹੁੰਦੇ ਹਨ। ਦਾਣੇ ਦਰਮਿਆਨੇ ਆਕਾਰ ਦੇ, ਗੋਲ, ਮੁਲਾਇਮ ਅਤੇ ਕਰੀਮੀ ਚਿੱਟੇ ਰੰਗ ਦੇ ਹੁੰਦੇ ਹਨ, ਅਤੇ ਬੀਜ ਪੱਤਰ ਪੀਲੇ ਹੁੰਦੇ ਹਨ। ਝਾੜ 25 q/ha ਹੈ। ਇਹ ਪੂਰੇ ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਲਈ ਸਿਫ਼ਾਰਸ਼ ਕੀਤੀ ਗਈ ਹੈ। ਇਹ ਚਿੱਟੇ ਰੋਗ ਅਤੇ ਕੁੰਗੀ ਦੋਵਾਂ ਦੀ ਰੋਧਕ ਹੈ।", "local_synonyms": ["ਮਟਰ", "IPFD-12-8"]}, {"variety_id": "091e4050-62c5-46c9-87e9-67187cfe4134", "language_code": "gu", "display_name": "વટાણા IPFD 12-8 (આકાશ)", "short_description": "120-130 દિવસની, ઠીંગણા અને પાંદડાવાળા છોડવાળી કઠોળ વટાણાની જાત, જેનું ઉત્પાદન 25 q/ha છે અને જે ભૂકી છારા તથા ગેરુ સામે પ્રતિકારક છે.", "detailed_description": "IPFD 12-8 (આકાશ) કઠોળ વટાણાની જાત છે, જે ICAR-ભારતીય કઠોળ સંશોધન સંસ્થા, કાનપુર દ્વારા 2020માં બહાર પાડવામાં આવી. પાકનો સમયગાળો 120-130 દિવસ છે. છોડ ઠીંગણા અને પાંદડાવાળા હોય છે. દાણા મધ્યમ કદના, ગોળ, લીસા અને મલાઈ જેવા સફેદ રંગના હોય છે, અને બીજપત્ર પીળા હોય છે. ઉત્પાદન 25 q/ha છે. તેની ભલામણ સમગ્ર ઉત્તર પ્રદેશ માટે કરવામાં આવી છે. તે ભૂકી છારો અને ગેરુ, બંને સામે પ્રતિકારક છે.", "local_synonyms": ["વટાણા", "IPFD-12-8"]}, {"variety_id": "091e4050-62c5-46c9-87e9-67187cfe4134", "language_code": "ta", "display_name": "வயல் பட்டாணி IPFD 12-8 (ஆகாஷ்)", "short_description": "120-130 நாட்கள் வயதுடைய, குட்டையான, அதிக இலைகள் கொண்ட வயல் பட்டாணி ரகம்; மகசூல் 25 q/ha; சாம்பல் நோய் மற்றும் துரு நோய்க்கு எதிர்ப்புத் திறன் கொண்டது.", "detailed_description": "IPFD 12-8 (ஆகாஷ்) என்பது ICAR-இந்திய பயறு வகை ஆராய்ச்சி நிறுவனம், கான்பூர் 2020-ல் வெளியிட்ட வயல் பட்டாணி ரகம் ஆகும். பயிரின் வயது 120-130 நாட்கள். செடிகள் குட்டையாகவும் அதிக இலைகளுடனும் இருக்கும். விதைகள் நடுத்தர அளவில், உருண்டையாக, வழுவழுப்பாக, கிரீம் கலந்த வெள்ளை நிறத்தில் இருக்கும்; விதையிலைகள் மஞ்சள் நிறம். மகசூல் 25 q/ha. இது உத்தரப் பிரதேசம் முழுவதற்கும் பரிந்துரைக்கப்படுகிறது. இது சாம்பல் நோய் மற்றும் துரு நோய் இரண்டிற்கும் எதிர்ப்புத் திறன் கொண்டது.", "local_synonyms": ["வயல் பட்டாணி", "IPFD-12-8"]}, {"variety_id": "091e4050-62c5-46c9-87e9-67187cfe4134", "language_code": "te", "display_name": "బఠాణీ IPFD 12-8 (ఆకాశ్)", "short_description": "120-130 రోజుల కాలపరిమితి గల, పొట్టిగా, ఆకులు ఎక్కువగా ఉండే పప్పుధాన్యపు బఠాణీ రకం; దిగుబడి 25 q/ha; బూడిద తెగులు మరియు తుప్పు తెగులుకు నిరోధక శక్తి కలిగి ఉంది.", "detailed_description": "IPFD 12-8 (ఆకాశ్) పప్పుధాన్యపు బఠాణీ రకం. దీనిని ICAR-భారతీయ పప్పుధాన్యాల పరిశోధన సంస్థ, కాన్పూర్ 2020లో విడుదల చేసింది. పంట కాలం 120-130 రోజులు. మొక్కలు పొట్టిగా, ఆకులు ఎక్కువగా ఉంటాయి. గింజలు మధ్యస్థ పరిమాణంలో, గుండ్రంగా, నునుపుగా, క్రీమ్ కలిసిన తెలుపు రంగులో ఉంటాయి; బీజదళాలు పసుపు రంగులో ఉంటాయి. దిగుబడి 25 q/ha. ఇది ఉత్తర ప్రదేశ్ మొత్తానికి సిఫార్సు చేయబడింది. ఇది బూడిద తెగులు మరియు తుప్పు తెగులు రెండింటికీ నిరోధక శక్తి కలిగి ఉంది.", "local_synonyms": ["బఠాణీ", "IPFD-12-8"]}, {"variety_id": "091e4050-62c5-46c9-87e9-67187cfe4134", "language_code": "kn", "display_name": "ಬಟಾಣಿ IPFD 12-8 (ಆಕಾಶ್)", "short_description": "120-130 ದಿನಗಳ ಅವಧಿಯ, ಗಿಡ್ಡ ಮತ್ತು ಹೆಚ್ಚು ಎಲೆಗಳಿರುವ ಕಾಳು ಬಟಾಣಿ ತಳಿ; ಇಳುವರಿ 25 q/ha; ಬೂದಿ ರೋಗ ಮತ್ತು ತುಕ್ಕು ರೋಗಕ್ಕೆ ನಿರೋಧಕ.", "detailed_description": "IPFD 12-8 (ಆಕಾಶ್) ಕಾಳು ಬಟಾಣಿಯ ತಳಿಯಾಗಿದ್ದು, ICAR-ಭಾರತೀಯ ದ್ವಿದಳ ಧಾನ್ಯ ಸಂಶೋಧನಾ ಸಂಸ್ಥೆ, ಕಾನ್ಪುರ 2020ರಲ್ಲಿ ಬಿಡುಗಡೆ ಮಾಡಿದೆ. ಬೆಳೆಯ ಅವಧಿ 120-130 ದಿನಗಳು. ಗಿಡಗಳು ಗಿಡ್ಡವಾಗಿದ್ದು ಹೆಚ್ಚು ಎಲೆಗಳನ್ನು ಹೊಂದಿರುತ್ತವೆ. ಕಾಳುಗಳು ಮಧ್ಯಮ ಗಾತ್ರದ, ದುಂಡಗಿನ, ನಯವಾದ ಮತ್ತು ಕೆನೆ ಮಿಶ್ರಿತ ಬಿಳಿ ಬಣ್ಣದವು; ಬೀಜದಳಗಳು ಹಳದಿ ಬಣ್ಣದವು. ಇಳುವರಿ 25 q/ha. ಇದನ್ನು ಇಡೀ ಉತ್ತರ ಪ್ರದೇಶಕ್ಕೆ ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ. ಇದು ಬೂದಿ ರೋಗ ಮತ್ತು ತುಕ್ಕು ರೋಗ ಎರಡಕ್ಕೂ ನಿರೋಧಕವಾಗಿದೆ.", "local_synonyms": ["ಬಟಾಣಿ", "IPFD-12-8"]}, {"variety_id": "bce3b757-1a30-4568-81cd-42cbfe0bcea9", "language_code": "en", "display_name": "Field Pea IPFD 2014-2", "short_description": "A dwarf field pea variety maturing in 102 days, yielding 2270 kg/ha and resistant to powdery mildew.", "detailed_description": "IPFD 2014-2 is a field pea variety from ICAR-Indian Institute of Pulses Research, Kanpur. It matures in 102 days. The plants are dwarf and fall in the dwarf category. The seeds are bold, with a mottled violet-tan colour. The yield is 2270 kg/ha. It is recommended for the central zone, which covers Madhya Pradesh, Chhattisgarh, Maharashtra and parts of Rajasthan. It is resistant to powdery mildew and moderately resistant to Ascochyta blight. It is also moderately resistant to pod borer, aphid and leaf miner.", "local_synonyms": ["IPFD-2014-2"]}, {"variety_id": "bce3b757-1a30-4568-81cd-42cbfe0bcea9", "language_code": "hi", "display_name": "मटर (दलहनी) IPFD 2014-2", "short_description": "102 दिनों में पकने वाली बौनी दलहनी मटर की किस्म, जिसकी उपज 2270 kg/ha है और जो भभूतिया रोग (चूर्णिल आसिता) के प्रति प्रतिरोधी है।", "detailed_description": "IPFD 2014-2 दलहनी मटर की किस्म है, जो ICAR-भारतीय दलहन अनुसंधान संस्थान, कानपुर की है। यह 102 दिनों में पक जाती है। पौधे बौने होते हैं और बौनी श्रेणी में आते हैं। दाने मोटे होते हैं और उनका रंग चितकबरा बैंगनी-भूरा होता है। उपज 2270 kg/ha है। इसकी सिफारिश मध्य क्षेत्र के लिए की गई है, जिसमें मध्य प्रदेश, छत्तीसगढ़, महाराष्ट्र और राजस्थान के कुछ भाग आते हैं। यह भभूतिया रोग (चूर्णिल आसिता) के प्रति प्रतिरोधी और एस्कोकाइटा झुलसा के प्रति मध्यम प्रतिरोधी है। यह फली छेदक, माहू और पत्ती सुरंगक (लीफ माइनर) के प्रति भी मध्यम प्रतिरोधी है।", "local_synonyms": ["मटर (दलहनी)", "IPFD-2014-2"]}, {"variety_id": "bce3b757-1a30-4568-81cd-42cbfe0bcea9", "language_code": "mr", "display_name": "वाटाणा (कडधान्य) IPFD 2014-2", "short_description": "102 दिवसांत तयार होणारा बुटका कडधान्य वाटाण्याचा वाण; उत्पादन 2270 kg/ha, भुरी रोगास प्रतिकारक्षम.", "detailed_description": "IPFD 2014-2 हा ICAR-भारतीय कडधान्य संशोधन संस्था, कानपूर यांचा कडधान्य वाटाण्याचा वाण आहे. हा वाण 102 दिवसांत तयार होतो. झाडे बुटकी असून बुटक्या गटात मोडतात. दाणे टपोरे असून त्यांचा रंग ठिपकेदार जांभळट-तपकिरी असतो. उत्पादन 2270 kg/ha मिळते. हा वाण मध्य विभागासाठी शिफारस केलेला आहे; यात मध्य प्रदेश, छत्तीसगड, महाराष्ट्र आणि राजस्थानचा काही भाग येतो. हा वाण भुरी रोगास प्रतिकारक्षम आणि ॲस्कोकायटा करपा रोगास मध्यम प्रतिकारक्षम आहे. शेंगा पोखरणारी अळी, मावा आणि पाने पोखरणारी अळी (लीफ मायनर) यांनाही तो मध्यम प्रतिकारक्षम आहे.", "local_synonyms": ["वाटाणा (कडधान्य)", "IPFD-2014-2"]}, {"variety_id": "bce3b757-1a30-4568-81cd-42cbfe0bcea9", "language_code": "pa", "display_name": "ਮਟਰ IPFD 2014-2", "short_description": "102 ਦਿਨਾਂ ਵਿੱਚ ਪੱਕਣ ਵਾਲੀ ਮਧਰੀ ਦਾਲ ਵਾਲੇ ਮਟਰ ਦੀ ਕਿਸਮ, ਜਿਸ ਦਾ ਝਾੜ 2270 kg/ha ਹੈ ਅਤੇ ਜੋ ਚਿੱਟੇ ਰੋਗ ਦੀ ਰੋਧਕ ਹੈ।", "detailed_description": "IPFD 2014-2 ਦਾਲ ਵਾਲੇ ਮਟਰ ਦੀ ਕਿਸਮ ਹੈ, ਜੋ ICAR-ਭਾਰਤੀ ਦਾਲਾਂ ਖੋਜ ਸੰਸਥਾਨ, ਕਾਨਪੁਰ ਦੀ ਹੈ। ਇਹ 102 ਦਿਨਾਂ ਵਿੱਚ ਪੱਕ ਜਾਂਦੀ ਹੈ। ਬੂਟੇ ਮਧਰੇ ਹੁੰਦੇ ਹਨ ਅਤੇ ਮਧਰੀ ਸ਼੍ਰੇਣੀ ਵਿੱਚ ਆਉਂਦੇ ਹਨ। ਦਾਣੇ ਮੋਟੇ ਹੁੰਦੇ ਹਨ ਅਤੇ ਉਨ੍ਹਾਂ ਦਾ ਰੰਗ ਡੱਬਖੜੱਬਾ ਜਾਮਣੀ-ਭੂਰਾ ਹੁੰਦਾ ਹੈ। ਝਾੜ 2270 kg/ha ਹੈ। ਇਹ ਕੇਂਦਰੀ ਖੇਤਰ ਲਈ ਸਿਫ਼ਾਰਸ਼ ਕੀਤੀ ਗਈ ਹੈ, ਜਿਸ ਵਿੱਚ ਮੱਧ ਪ੍ਰਦੇਸ਼, ਛੱਤੀਸਗੜ੍ਹ, ਮਹਾਰਾਸ਼ਟਰ ਅਤੇ ਰਾਜਸਥਾਨ ਦੇ ਕੁਝ ਹਿੱਸੇ ਸ਼ਾਮਲ ਹਨ। ਇਹ ਚਿੱਟੇ ਰੋਗ ਦੀ ਰੋਧਕ ਅਤੇ ਐਸਕੋਕਾਈਟਾ ਝੁਲਸ ਰੋਗ ਪ੍ਰਤੀ ਦਰਮਿਆਨੀ ਰੋਧਕ ਹੈ। ਇਹ ਫ਼ਲੀ ਛੇਦਕ ਸੁੰਡੀ, ਚੇਪੇ ਅਤੇ ਪੱਤੇ ਦੇ ਸੁਰੰਗੀ ਕੀੜੇ ਪ੍ਰਤੀ ਵੀ ਦਰਮਿਆਨੀ ਰੋਧਕ ਹੈ।", "local_synonyms": ["ਮਟਰ", "IPFD-2014-2"]}, {"variety_id": "bce3b757-1a30-4568-81cd-42cbfe0bcea9", "language_code": "gu", "display_name": "વટાણા IPFD 2014-2", "short_description": "102 દિવસમાં પાકતી ઠીંગણી કઠોળ વટાણાની જાત, જેનું ઉત્પાદન 2270 kg/ha છે અને જે ભૂકી છારા સામે પ્રતિકારક છે.", "detailed_description": "IPFD 2014-2 એ ICAR-ભારતીય કઠોળ સંશોધન સંસ્થા, કાનપુરની કઠોળ વટાણાની જાત છે. તે 102 દિવસમાં પાકે છે. છોડ ઠીંગણા હોય છે અને ઠીંગણી શ્રેણીમાં આવે છે. દાણા મોટા હોય છે અને તેનો રંગ ટપકાંવાળો જાંબલી-બદામી હોય છે. ઉત્પાદન 2270 kg/ha છે. તેની ભલામણ મધ્ય વિસ્તાર માટે કરવામાં આવી છે, જેમાં મધ્ય પ્રદેશ, છત્તીસગઢ, મહારાષ્ટ્ર અને રાજસ્થાનના કેટલાક ભાગો આવે છે. તે ભૂકી છારા સામે પ્રતિકારક અને એસ્કોકાઇટા ઝાળ સામે મધ્યમ પ્રતિકારક છે. તે શીંગ કોરી ખાનાર ઇયળ, મોલો અને પાન કોરિયા સામે પણ મધ્યમ પ્રતિકારક છે.", "local_synonyms": ["વટાણા", "IPFD-2014-2"]}, {"variety_id": "bce3b757-1a30-4568-81cd-42cbfe0bcea9", "language_code": "ta", "display_name": "வயல் பட்டாணி IPFD 2014-2", "short_description": "102 நாட்களில் முதிர்ச்சியடையும் குட்டையான வயல் பட்டாணி ரகம்; மகசூல் 2270 kg/ha; சாம்பல் நோய்க்கு எதிர்ப்புத் திறன் கொண்டது.", "detailed_description": "IPFD 2014-2 என்பது ICAR-இந்திய பயறு வகை ஆராய்ச்சி நிறுவனம், கான்பூரின் வயல் பட்டாணி ரகம் ஆகும். இது 102 நாட்களில் முதிர்ச்சியடையும். செடிகள் குட்டையானவை; குட்டை வகைப் பிரிவைச் சேர்ந்தவை. விதைகள் பருமனானவை; அவை ஊதா கலந்த பழுப்பு நிறத்தில் புள்ளிகளுடன் இருக்கும். மகசூல் 2270 kg/ha. இது மத்திய மண்டலத்திற்குப் பரிந்துரைக்கப்படுகிறது; இதில் மத்தியப் பிரதேசம், சத்தீஸ்கர், மகாராஷ்டிரா மற்றும் ராஜஸ்தானின் சில பகுதிகள் அடங்கும். இது சாம்பல் நோய்க்கு எதிர்ப்புத் திறனும், அஸ்கோகைட்டா கருகல் நோய்க்கு மிதமான எதிர்ப்புத் திறனும் கொண்டது. காய்ப்புழு, அசுவினி மற்றும் இலைச் சுரங்கப் பூச்சிக்கும் இது மிதமான எதிர்ப்புத் திறன் கொண்டது.", "local_synonyms": ["வயல் பட்டாணி", "IPFD-2014-2"]}, {"variety_id": "bce3b757-1a30-4568-81cd-42cbfe0bcea9", "language_code": "te", "display_name": "బఠాణీ IPFD 2014-2", "short_description": "102 రోజుల్లో పక్వానికి వచ్చే పొట్టి పప్పుధాన్యపు బఠాణీ రకం; దిగుబడి 2270 kg/ha; బూడిద తెగులుకు నిరోధక శక్తి కలిగి ఉంది.", "detailed_description": "IPFD 2014-2 ICAR-భారతీయ పప్పుధాన్యాల పరిశోధన సంస్థ, కాన్పూర్‌కు చెందిన పప్పుధాన్యపు బఠాణీ రకం. ఇది 102 రోజుల్లో పక్వానికి వస్తుంది. మొక్కలు పొట్టిగా ఉంటాయి, పొట్టి రకాల వర్గంలోకి వస్తాయి. గింజలు లావుగా ఉంటాయి; వాటి రంగు ఊదా ఛాయ గల మచ్చల గోధుమ రంగు. దిగుబడి 2270 kg/ha. ఇది మధ్య మండలానికి సిఫార్సు చేయబడింది; ఇందులో మధ్యప్రదేశ్, ఛత్తీస్‌గఢ్, మహారాష్ట్ర మరియు రాజస్థాన్‌లోని కొన్ని ప్రాంతాలు ఉన్నాయి. ఇది బూడిద తెగులుకు నిరోధక శక్తి, ఆస్కోకైటా ఆకుమాడు తెగులుకు మధ్యస్థ నిరోధక శక్తి కలిగి ఉంది. కాయ తొలుచు పురుగు, పేనుబంక మరియు ఆకు తొలుచు పురుగులకు కూడా ఇది మధ్యస్థ నిరోధక శక్తి కలిగి ఉంది.", "local_synonyms": ["బఠాణీ", "IPFD-2014-2"]}, {"variety_id": "bce3b757-1a30-4568-81cd-42cbfe0bcea9", "language_code": "kn", "display_name": "ಬಟಾಣಿ IPFD 2014-2", "short_description": "102 ದಿನಗಳಲ್ಲಿ ಮಾಗುವ ಗಿಡ್ಡ ಕಾಳು ಬಟಾಣಿ ತಳಿ; ಇಳುವರಿ 2270 kg/ha; ಬೂದಿ ರೋಗಕ್ಕೆ ನಿರೋಧಕ.", "detailed_description": "IPFD 2014-2 ICAR-ಭಾರತೀಯ ದ್ವಿದಳ ಧಾನ್ಯ ಸಂಶೋಧನಾ ಸಂಸ್ಥೆ, ಕಾನ್ಪುರದ ಕಾಳು ಬಟಾಣಿ ತಳಿಯಾಗಿದೆ. ಇದು 102 ದಿನಗಳಲ್ಲಿ ಮಾಗುತ್ತದೆ. ಗಿಡಗಳು ಗಿಡ್ಡವಾಗಿದ್ದು ಗಿಡ್ಡ ವರ್ಗಕ್ಕೆ ಸೇರುತ್ತವೆ. ಕಾಳುಗಳು ದಪ್ಪವಾಗಿದ್ದು, ನೇರಳೆ ಛಾಯೆಯ ಚುಕ್ಕೆಗಳಿರುವ ಕಂದು ಬಣ್ಣದವು. ಇಳುವರಿ 2270 kg/ha. ಇದನ್ನು ಮಧ್ಯ ವಲಯಕ್ಕೆ ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ; ಇದರಲ್ಲಿ ಮಧ್ಯಪ್ರದೇಶ, ಛತ್ತೀಸ್‌ಗಢ, ಮಹಾರಾಷ್ಟ್ರ ಮತ್ತು ರಾಜಸ್ಥಾನದ ಕೆಲವು ಭಾಗಗಳು ಸೇರಿವೆ. ಇದು ಬೂದಿ ರೋಗಕ್ಕೆ ನಿರೋಧಕ ಮತ್ತು ಆಸ್ಕೋಕೈಟಾ ಅಂಗಮಾರಿ ರೋಗಕ್ಕೆ ಮಧ್ಯಮ ನಿರೋಧಕ. ಕಾಯಿ ಕೊರಕ, ಸಸ್ಯಹೇನು ಮತ್ತು ಎಲೆ ಸುರಂಗ ಕೀಟಕ್ಕೂ ಇದು ಮಧ್ಯಮ ನಿರೋಧಕವಾಗಿದೆ.", "local_synonyms": ["ಬಟಾಣಿ", "IPFD-2014-2"]}, {"variety_id": "44d675af-1a95-4176-8908-57fc9c911c61", "language_code": "en", "display_name": "Field Pea Pant Pea 243", "short_description": "A tall-category field pea variety for the rabi season, yielding 20-25 q/ha.", "detailed_description": "Pant Pea 243 is a field pea variety. It was released in 2018 by G.B. Pant University of Agriculture & Technology, Pantnagar, under AICRP-MULLaRP. The plants belong to the tall category. This variety is grown in the rabi season. Its yield is 20-25 q/ha. It is recommended for the Central Zone of India, which includes the states of Madhya Pradesh and Chhattisgarh and also parts of Rajasthan.", "local_synonyms": ["Pant-Pea-243"]}, {"variety_id": "44d675af-1a95-4176-8908-57fc9c911c61", "language_code": "hi", "display_name": "मटर (दलहनी) पंत पी 243", "short_description": "रबी मौसम के लिए ऊँची श्रेणी की दलहनी मटर की किस्म, जिसकी उपज 20-25 q/ha है।", "detailed_description": "पंत पी 243 दलहनी मटर की किस्म है। इसे वर्ष 2018 में जी.बी. पंत कृषि एवं प्रौद्योगिकी विश्वविद्यालय, पंतनगर ने AICRP-MULLaRP के अंतर्गत जारी किया। इसके पौधे ऊँची श्रेणी के हैं। यह किस्म रबी मौसम में उगाई जाती है। इसकी उपज 20-25 q/ha है। इसकी सिफारिश भारत के मध्य क्षेत्र के लिए की गई है, जिसमें मध्य प्रदेश और छत्तीसगढ़ राज्य तथा राजस्थान के कुछ भाग आते हैं।", "local_synonyms": ["मटर (दलहनी)", "Pant-Pea-243"]}, {"variety_id": "44d675af-1a95-4176-8908-57fc9c911c61", "language_code": "mr", "display_name": "वाटाणा (कडधान्य) पंत पी 243", "short_description": "रब्बी हंगामासाठी उंच गटातील कडधान्य वाटाण्याचा वाण; उत्पादन 20-25 q/ha.", "detailed_description": "पंत पी 243 हा कडधान्य वाटाण्याचा वाण आहे. जी.बी. पंत कृषी व तंत्रज्ञान विद्यापीठ, पंतनगर यांनी AICRP-MULLaRP अंतर्गत 2018 मध्ये हा वाण प्रसारित केला. याची झाडे उंच गटातील आहेत. हा वाण रब्बी हंगामात घेतला जातो. याचे उत्पादन 20-25 q/ha मिळते. हा वाण भारताच्या मध्य विभागासाठी शिफारस केलेला आहे; यात मध्य प्रदेश व छत्तीसगड ही राज्ये आणि राजस्थानचा काही भाग येतो.", "local_synonyms": ["वाटाणा (कडधान्य)", "Pant-Pea-243"]}, {"variety_id": "44d675af-1a95-4176-8908-57fc9c911c61", "language_code": "pa", "display_name": "ਮਟਰ ਪੰਤ ਪੀ 243", "short_description": "ਹਾੜ੍ਹੀ (ਰਬੀ) ਰੁੱਤ ਲਈ ਉੱਚੀ ਸ਼੍ਰੇਣੀ ਦੀ ਦਾਲ ਵਾਲੇ ਮਟਰ ਦੀ ਕਿਸਮ, ਜਿਸ ਦਾ ਝਾੜ 20-25 q/ha ਹੈ।", "detailed_description": "ਪੰਤ ਪੀ 243 ਦਾਲ ਵਾਲੇ ਮਟਰ ਦੀ ਕਿਸਮ ਹੈ। ਇਹ ਜੀ.ਬੀ. ਪੰਤ ਖੇਤੀਬਾੜੀ ਅਤੇ ਤਕਨਾਲੋਜੀ ਯੂਨੀਵਰਸਿਟੀ, ਪੰਤਨਗਰ ਵੱਲੋਂ AICRP-MULLaRP ਅਧੀਨ 2018 ਵਿੱਚ ਜਾਰੀ ਕੀਤੀ ਗਈ। ਇਸ ਦੇ ਬੂਟੇ ਉੱਚੀ ਸ਼੍ਰੇਣੀ ਦੇ ਹਨ। ਇਹ ਕਿਸਮ ਹਾੜ੍ਹੀ (ਰਬੀ) ਰੁੱਤ ਵਿੱਚ ਉਗਾਈ ਜਾਂਦੀ ਹੈ। ਇਸ ਦਾ ਝਾੜ 20-25 q/ha ਹੈ। ਇਹ ਭਾਰਤ ਦੇ ਕੇਂਦਰੀ ਖੇਤਰ ਲਈ ਸਿਫ਼ਾਰਸ਼ ਕੀਤੀ ਗਈ ਹੈ, ਜਿਸ ਵਿੱਚ ਮੱਧ ਪ੍ਰਦੇਸ਼ ਅਤੇ ਛੱਤੀਸਗੜ੍ਹ ਰਾਜ ਅਤੇ ਰਾਜਸਥਾਨ ਦੇ ਕੁਝ ਹਿੱਸੇ ਸ਼ਾਮਲ ਹਨ।", "local_synonyms": ["ਮਟਰ", "Pant-Pea-243"]}, {"variety_id": "44d675af-1a95-4176-8908-57fc9c911c61", "language_code": "gu", "display_name": "વટાણા પંત પી 243", "short_description": "રવી ઋતુ માટે ઊંચી શ્રેણીની કઠોળ વટાણાની જાત, જેનું ઉત્પાદન 20-25 q/ha છે.", "detailed_description": "પંત પી 243 કઠોળ વટાણાની જાત છે. તેને જી.બી. પંત કૃષિ અને ટેકનોલોજી યુનિવર્સિટી, પંતનગર દ્વારા AICRP-MULLaRP હેઠળ 2018માં બહાર પાડવામાં આવી. તેના છોડ ઊંચી શ્રેણીના છે. આ જાત રવી ઋતુમાં ઉગાડવામાં આવે છે. તેનું ઉત્પાદન 20-25 q/ha છે. તેની ભલામણ ભારતના મધ્ય વિસ્તાર માટે કરવામાં આવી છે, જેમાં મધ્ય પ્રદેશ અને છત્તીસગઢ રાજ્યો તથા રાજસ્થાનના કેટલાક ભાગો આવે છે.", "local_synonyms": ["વટાણા", "Pant-Pea-243"]}, {"variety_id": "44d675af-1a95-4176-8908-57fc9c911c61", "language_code": "ta", "display_name": "வயல் பட்டாணி பந்த் பீ 243", "short_description": "ராபி பருவத்திற்கான, உயரமான வகைப் பிரிவைச் சேர்ந்த வயல் பட்டாணி ரகம்; மகசூல் 20-25 q/ha.", "detailed_description": "பந்த் பீ 243 ஒரு வயல் பட்டாணி ரகம் ஆகும். இதை ஜி.பி. பந்த் வேளாண்மை மற்றும் தொழில்நுட்பப் பல்கலைக்கழகம், பந்த்நகர் AICRP-MULLaRP-இன் கீழ் 2018-ல் வெளியிட்டது. இதன் செடிகள் உயரமான வகைப் பிரிவைச் சேர்ந்தவை. இந்த ரகம் ராபி பருவத்தில் பயிரிடப்படுகிறது. இதன் மகசூல் 20-25 q/ha. இது இந்தியாவின் மத்திய மண்டலத்திற்குப் பரிந்துரைக்கப்படுகிறது; இதில் மத்தியப் பிரதேசம், சத்தீஸ்கர் மாநிலங்களும் ராஜஸ்தானின் சில பகுதிகளும் அடங்கும்.", "local_synonyms": ["வயல் பட்டாணி", "Pant-Pea-243"]}, {"variety_id": "44d675af-1a95-4176-8908-57fc9c911c61", "language_code": "te", "display_name": "బఠాణీ పంత్ పీ 243", "short_description": "రబీ కాలానికి, పొడవైన వర్గానికి చెందిన పప్పుధాన్యపు బఠాణీ రకం; దిగుబడి 20-25 q/ha.", "detailed_description": "పంత్ పీ 243 పప్పుధాన్యపు బఠాణీ రకం. దీనిని జి.బి. పంత్ వ్యవసాయ మరియు సాంకేతిక విశ్వవిద్యాలయం, పంత్‌నగర్ AICRP-MULLaRP కింద 2018లో విడుదల చేసింది. దీని మొక్కలు పొడవైన వర్గానికి చెందినవి. ఈ రకాన్ని రబీ కాలంలో సాగు చేస్తారు. దీని దిగుబడి 20-25 q/ha. ఇది భారతదేశ మధ్య మండలానికి సిఫార్సు చేయబడింది; ఇందులో మధ్యప్రదేశ్, ఛత్తీస్‌గఢ్ రాష్ట్రాలు మరియు రాజస్థాన్‌లోని కొన్ని ప్రాంతాలు ఉన్నాయి.", "local_synonyms": ["బఠాణీ", "Pant-Pea-243"]}, {"variety_id": "44d675af-1a95-4176-8908-57fc9c911c61", "language_code": "kn", "display_name": "ಬಟಾಣಿ ಪಂತ್ ಪೀ 243", "short_description": "ಹಿಂಗಾರು (ರಬಿ) ಹಂಗಾಮಿಗೆ ಎತ್ತರದ ವರ್ಗದ ಕಾಳು ಬಟಾಣಿ ತಳಿ; ಇಳುವರಿ 20-25 q/ha.", "detailed_description": "ಪಂತ್ ಪೀ 243 ಕಾಳು ಬಟಾಣಿಯ ತಳಿಯಾಗಿದೆ. ಇದನ್ನು ಜಿ.ಬಿ. ಪಂತ್ ಕೃಷಿ ಮತ್ತು ತಂತ್ರಜ್ಞಾನ ವಿಶ್ವವಿದ್ಯಾಲಯ, ಪಂತ್‌ನಗರ AICRP-MULLaRP ಅಡಿಯಲ್ಲಿ 2018ರಲ್ಲಿ ಬಿಡುಗಡೆ ಮಾಡಿದೆ. ಇದರ ಗಿಡಗಳು ಎತ್ತರದ ವರ್ಗಕ್ಕೆ ಸೇರಿವೆ. ಈ ತಳಿಯನ್ನು ಹಿಂಗಾರು (ರಬಿ) ಹಂಗಾಮಿನಲ್ಲಿ ಬೆಳೆಯಲಾಗುತ್ತದೆ. ಇದರ ಇಳುವರಿ 20-25 q/ha. ಇದನ್ನು ಭಾರತದ ಮಧ್ಯ ವಲಯಕ್ಕೆ ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ; ಇದರಲ್ಲಿ ಮಧ್ಯಪ್ರದೇಶ ಮತ್ತು ಛತ್ತೀಸ್‌ಗಢ ರಾಜ್ಯಗಳು ಹಾಗೂ ರಾಜಸ್ಥಾನದ ಕೆಲವು ಭಾಗಗಳು ಸೇರಿವೆ.", "local_synonyms": ["ಬಟಾಣಿ", "Pant-Pea-243"]}, {"variety_id": "5008b41d-7af7-4dd2-b794-7f4d4ae6d9c9", "language_code": "en", "display_name": "Field Pea Pant Pea 484", "short_description": "An open-pollinated rabi field pea variety maturing in 120 days, yielding 23.33 q/ha and resistant to Ascochyta blight.", "detailed_description": "Pant Pea 484 is an open-pollinated (OPV) field pea variety released in 2024 by ICAR-AICRP on Pulses, G.B. Pant University of Agriculture and Technology, Pantnagar, Uttarakhand. It matures in 120 days. Its protein content is 26.17%. The yield is 23.33 q/ha. It is a rabi season variety and suits both rainfed and irrigated conditions. It is recommended for Punjab, Haryana, Delhi, North-West and Central Rajasthan, Western Uttar Pradesh, the plains of Uttarakhand, and Jammu and Kashmir. It is resistant to Ascochyta blight and moderately resistant to rust and powdery mildew. It is also moderately resistant to aphid and pod borer.", "local_synonyms": ["Pant-Pea-484"]}, {"variety_id": "5008b41d-7af7-4dd2-b794-7f4d4ae6d9c9", "language_code": "hi", "display_name": "मटर (दलहनी) पंत पी 484", "short_description": "120 दिनों में पकने वाली खुली पर